+ * src/legacy/ must not be edited, so POST /import uses this parser instead.)
+ */
+export function parseCsv(input: string): CsvRecord[] {
+  const text = input.charCodeAt(0) === 0xfeff ? input.slice(1) : input;
+  const records: CsvRecord[] = [];
+
+  let cells: string[] = [];
+  let cell = '';
+  let inQuotes = false;
+  let fieldStart = true; // at the first character of a field
+  let line = 1;
+  let recordLine = 1;
+  let quoteLine = 1;
+
+  const endCell = () => {
+    cells.push(cell);
+    cell = '';
+    fieldStart = true;
+  };
+  const endRecord = () => {
+    endCell();
+    const blank = cells.length === 1 && cells[0].trim() === '';
+    if (!blank) records.push({ cells, line: recordLine });
+    cells = [];
+  };
+
+  for (let i = 0; i < text.length; i++) {
+    const ch = text[i];
+    if (inQuotes) {
+      if (ch === '"') {
+        if (text[i + 1] === '"') {
+          cell += '"';
+          i++;
+        } else {
+          inQuotes = false;
+        }
+      } else {
+        if (ch === '\n') line++;
+        cell += ch;
+      }
+      continue;
+    }
+    if (ch === '"' && fieldStart) {
+      inQuotes = true;
+      quoteLine = line;
+      fieldStart = false;
+    } else if (ch === ',') {
+      endCell();
+    } else if (ch === '\n' || (ch === '\r' && text[i + 1] === '\n')) {
+      if (ch === '\r') i++;
+      endRecord();
+      line++;
+      recordLine = line;
+    } else {
+      cell += ch;
+      fieldStart = false;
+    }
+  }
+
+  if (inQuotes) {
+    throw new HttpError(
+      400,
+      'INVALID_CSV',
+      `CSV ungültig: Das Anführungszeichen in Zeile ${quoteLine} wird nicht geschlossen.`,
+    );
+  }
+  if (cell !== '' || cells.length > 0) endRecord();
+  return records;
+}
+
+export interface ImportRow extends LegacyRow {
+  /** Line in the uploaded file where this row starts, for error reports. */
+  line: number;
+}
+
+/**
+ * Parses the legacy import format (header: tracking,carrier,service,name,street,zip,city,country,phone)
+ * into the same row shape as the legacy parser, but with proper CSV quoting and real line numbers.
+ */
+export function parseImportCsv(text: string): ImportRow[] {
+  const [headerRecord, ...records] = parseCsv(text);
+  if (!headerRecord) return [];
+  const header = headerRecord.cells.map((h) => h.trim().toLowerCase());
+
+  return records.map(({ cells, line }) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
+    const phone = get('phone');
+    return {
+      line,
+      tracking_number: get('tracking'),
+      carrier: mapLegacyCarrier(get('carrier')),
+      service_level: get('service') || 'standard',
+      recipient: {
+        name: get('name'),
+        street: get('street'),
+        zip: get('zip'),
+        city: get('city'),
+        country: get('country') || 'AT',
+        ...(phone ? { phone } : {}),
+      },
+    };
+  });
